<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Spatie\Activitylog\LogOptions;use Spatie\Activitylog\Traits\LogsActivity;
class AccionCompromiso extends Model{use LogsActivity;protected static function booted():void{static::addGlobalScope('responsable',function($query){$user=auth()->user();$id=$user?->hasRole('responsable')?$user->responsable?->id:null;if($id)$query->where(fn($q)=>$q->whereHas('responsables',fn($r)=>$r->where('responsables.id',$id))->orWhereHas('accionesEjecucion.responsables',fn($r)=>$r->where('responsables.id',$id)));});static::created(function($model){$user=auth()->user();$id=$user?->hasRole('responsable')?$user->responsable?->id:null;if($id)$model->responsables()->syncWithoutDetaching([$id]);});}protected $table='acciones_compromisos';protected $guarded=[];protected $casts=['fecha_compromiso'=>'date','fecha_limite'=>'date','fecha_proximo_paso'=>'date','requiere_decision'=>'boolean','presupuesto_estimado'=>'decimal:2','porcentaje'=>'integer','documentos'=>'array'];public function necesidad(){return $this->belongsTo(Necesidad::class);}public function accionesEjecucion(){return $this->hasMany(AccionEjecucion::class);}public function comunidad(){return $this->belongsTo(Comunidad::class);}public function responsablePrincipal(){return $this->belongsTo(Responsable::class,'responsable_id');}public function responsables(){return $this->belongsToMany(Responsable::class,'accion_compromiso_responsable')->withTimestamps();}public function getAvanceCalculadoAttribute(): int { return (int) round($this->accionesEjecucion->avg('avance') ?? $this->porcentaje ?? 0); } public function getActivitylogOptions():LogOptions{return LogOptions::defaults()->logAll()->logOnlyDirty();}}